import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const a="/assets/238_34e57382-d04c-4fb6-9094-9757330b7b04.C_0b1ItF.png",g=JSON.parse('{"title":"Cracking the password of a dedicated server machine","description":"","frontmatter":{"title":"Cracking the password of a dedicated server machine"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/cracking-the-password-of-a-dedicated-server-machine.md","filePath":"operations-knowledge-base/dedicated-server/cracking-the-password-of-a-dedicated-server-machine.md","lastUpdated":1794292919000}'),n={name:"operations-knowledge-base/dedicated-server/cracking-the-password-of-a-dedicated-server-machine.md"};function i(d,t,c,h,u,l){return o(),r("div",null,[...t[0]||(t[0]=[s('<p>When you forget the server administrator password (<strong>Administrator/root</strong>) or need to reset it to improve security, you can use the <strong>&quot;Crack the code&quot;</strong> feature in the control panel to quickly reset the password.</p><h2 id="i-access-path" tabindex="-1">I. Access Path <a class="header-anchor" href="#i-access-path" aria-label="Permalink to &quot;I. Access Path&quot;">​</a></h2><p>Log in to the platform and go to the <strong>&quot;Customer Center&quot;</strong>.</p><p>Under <strong>&quot;My Orders&quot;</strong>, click <strong>&quot;Dedicated&quot;</strong>. Alternatively, go to <strong>&quot;Product Management&quot;</strong>, click <strong>&quot;Dedicated&quot;</strong>, and filter the server list by region and status.</p><p>In the product list, locate the target server and open the <strong>&quot;Product Details&quot;</strong> page.</p><p>Under the <strong>&quot;Server Information&quot;</strong> tab, find and click <strong>&quot;Crack the code&quot;</strong> to open the password reset window.</p><p><img src="'+a+'" alt=""></p><h2 id="ii-steps" tabindex="-1">II. Steps <a class="header-anchor" href="#ii-steps" aria-label="Permalink to &quot;II. Steps&quot;">​</a></h2><h3 id="_1-reset-the-default-administrator-password" tabindex="-1">1. Reset the Default Administrator Password <a class="header-anchor" href="#_1-reset-the-default-administrator-password" aria-label="Permalink to &quot;1. Reset the Default Administrator Password&quot;">​</a></h3><p>After the <strong>&quot;Crack the code&quot;</strong> window opens, the system will reset the password for the default administrator account by default:</p><ul><li><strong>Administrator</strong> (Windows)</li><li><strong>root</strong> (Linux, such as Ubuntu and CentOS)</li></ul><p>In the <strong>&quot;Password&quot;</strong> field, enter the new password you want to set (a random password may be generated by default).</p><h3 id="_2-reset-a-custom-user-password-optional" tabindex="-1">2. Reset a Custom User Password (Optional) <a class="header-anchor" href="#_2-reset-a-custom-user-password-optional" aria-label="Permalink to &quot;2. Reset a Custom User Password (Optional)&quot;">​</a></h3><p>If you need to reset the password for a user other than the administrator, select the option in the <strong>&quot;Crack Others&quot;</strong> section:</p><ul><li><strong>&quot;After selecting, the system will reset the password for a custom user&quot;</strong></li></ul><p>Then specify the custom username to reset.</p><h3 id="_3-confirm-the-reset" tabindex="-1">3. Confirm the Reset <a class="header-anchor" href="#_3-confirm-the-reset" aria-label="Permalink to &quot;3. Confirm the Reset&quot;">​</a></h3><p>Carefully check the new password. When ready, click <strong>&quot;Confirm&quot;</strong> in the lower-right corner of the window. The system will begin the password reset process.</p><p>After the reset is successful, go to <strong>&quot;Information software&quot;</strong> and click <strong>&quot;*&quot;</strong> to view the updated password.</p>',19)])])}const m=e(n,[["render",i]]);export{g as __pageData,m as default};
